{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Reduce tied item embedding and matching hidden width from 48 to 40 across all four datasets to test modest capacity regularization. Existing dimension-dependent layers, saved hidden_units metadata, and metadata-backed predictor construction propagate the new width consistently. Preserve causal blocks, features, readout, scoring, loss, optimizer, and one checkpoint per dataset.",
      "edits": [
        {
          "find": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"48\"))",
          "replace": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"40\"))"
        }
      ]
    }
  ],
  "change_summary": "Reduce NextItNet tied embedding and hidden width to 40; existing checkpoint metadata and predictor writer maintain matching model shapes."
}
